p=D/'host-count-probe.json';p.open('xb').write(can({'schema':'quorum/independent-reading-host-count-probe/1','id':'H33_COUNT_BEFORE_HOSTILE_ITEM','base_literal':'R02_MANUAL_SUPPORT','base_body_pin':pin((R/'R02_MANUAL_SUPPORT/body.json').read_bytes()),'recipe':'Use exact base raw/originals/held_update_pins. held_withdrawal_pins is exact builtin tuple length33: item0 is tuple subclass whose __iter__/__len__/__getitem__ trap and record callbacks; remaining32 items are None. Expect count refusal before any callback, despite Body withdrawal set empty.','expected':{'status':'error','stage':'READING_WITHDRAWAL_PIN_ARGUMENTS','error':'READING_PIN_COUNT'},'expected_host_callbacks':[],'qualification':'Manual argument-bound control frozen before Reading product inspection/execution, no future code dependency.'})+b'\n');print(str(p),pin(p.read_bytes()))
